@RunWith(MockitoJUnitRunner.class)
public class BuildGlobalNamespace_collect_TriageGen0Test {

    private BuildGlobalNamespace buildGlobalNamespace;
    private JSModule module;
    private Scope scope;

    @Before
    public void setUp() {
        module = mock(JSModule.class);
        scope = mock(Scope.class);
        // We use a spy to mock the internal private/protected methods called by collect
        buildGlobalNamespace = spy(new BuildGlobalNamespace());
    }

    private Node mockNode(int type, String value) {
        Node n = mock(Node.class);
        when(n.getType()).thenReturn(type);
        if (value != null) {
            when(n.getString()).thenReturn(value);
        }
        return n;
    }

    @Test
    public void testCollect_StringKey_ObjectLit() {
        Node n = mockNode(Token.STRING_KEY, "key");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.isObjectLit()).thenReturn(true);

        // Mock getNameForObjLitKey via spy
        doReturn("key").when(buildGlobalNamespace).getNameForObjLitKey(n);

        // Mock getValueType
        Node child = mock(Node.class);
        when(n.getFirstChild()).thenReturn(child);
        // Assuming getValueType is accessible or we mock the behavior via internal flow
        // Since we can't easily mock private getValueType without PowerMock, 
        // we assume it's part of the class logic. 
        // For this test, we focus on the branch coverage.

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("key"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("key"), eq(false), any());
    }

    @Test
    public void testCollect_StringKey_NoParent() {
        Node n = mockNode(Token.STRING_KEY, "key");
        when(n.getParent()).thenReturn(null);
        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).isGlobalNameReference(any(), any());
    }

    @Test
    public void testCollect_GetterDef_ObjectLit() {
        Node n = mockNode(Token.GETTER_DEF, null);
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.isObjectLit()).thenReturn(true);
        doReturn("getProp").when(buildGlobalNamespace).getNameForObjLitKey(n);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("getProp"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("getProp"), eq(false), eq(Name.Type.GET));
    }

    @Test
    public void testCollect_SetterDef_ObjectLit() {
        Node n = mockNode(Token.SETTER_DEF, null);
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.isObjectLit()).thenReturn(true);
        doReturn("setProp").when(buildGlobalNamespace).getNameForObjLitKey(n);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("setProp"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("setProp"), eq(false), eq(Name.Type.SET));
    }

    @Test
    public void testCollect_Name_Var() {
        Node n = mockNode(Token.NAME, "x");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.VAR);

        Node rvalue = mock(Node.class);
        when(n.getFirstChild()).thenReturn(rvalue);
        // We assume getValueType is a method in the same class
        // To avoid complex mocking, we rely on the fact that if rvalue is null, type is OTHER
        when(n.getFirstChild()).thenReturn(null);

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("x"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("x"), eq(false), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_Name_AssignLeft() {
        Node n = mockNode(Token.NAME, "x");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(n);

        Node next = mock(Node.class);
        when(n.getNext()).thenReturn(next);
        // Here type would be determined by getValueType(next)

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("x"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        // Verification depends on getValueType implementation, but we check the call
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("x"), eq(false), any());
    }

    @Test
    public void testCollect_Name_GetProp_Return() {
        Node n = mockNode(Token.NAME, "x");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.GETPROP);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).isGlobalNameReference(any(), any());
    }

    @Test
    public void testCollect_Name_Function() {
        Node n = mockNode(Token.NAME, "func");
        Node parent = mock(Node.class);
        Node grandparent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.FUNCTION);
        when(parent.getParent()).thenReturn(grandparent);

        // Test case: Function Expression (should return)
        // Note: NodeUtil.isFunctionExpression is likely static, 
        // this test assumes standard Rhino Node behavior or mocking via spy if possible.
        // Since it's static, we'll trigger the 'return' by ensuring it's treated as a function expression.
        // For the sake of this unit test structure, we assume the branch is reachable.

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("func"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        // If it's a function declaration (not expression), it hits handleSetFromGlobal
    }

    @Test
    public void testCollect_Name_IncDec() {
        Node n = mockNode(Token.NAME, "i");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.INC);

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("i"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("i"), eq(false), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_GetProp_Assign() {
        Node n = mockNode(Token.GETPROP, null);
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(n);

        Node next = mock(Node.class);
        when(n.getNext()).thenReturn(next);
        when(n.getQualifiedName()).thenReturn("a.b");

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("a.b"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("a.b"), eq(true), any());
    }

    @Test
    public void testCollect_GetProp_IncDec() {
        Node n = mockNode(Token.GETPROP, null);
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.INC);
        when(n.getQualifiedName()).thenReturn("a.b");

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("a.b"), eq(scope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("a.b"), eq(false), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_GetProp_GetProp_Return() {
        Node n = mockNode(Token.GETPROP, null);
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.GETPROP);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).isGlobalNameReference(any(), any());
    }

    @Test
    public void testCollect_Get_NonGlobal() {
        Node n = mockNode(Token.NAME, "local");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(n);

        doReturn(false).when(buildGlobalNamespace).isGlobalNameReference(eq("local"), eq(scope));

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
    }

    @Test
    public void testCollect_Get_Global() {
        Node n = mockNode(Token.NAME, "globalVar");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        // Default case for parent type in NAME switch is not isSet
        when(parent.getType()).thenReturn(Token.EXPRESSION); 

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("globalVar"), eq(scope));

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleGet(eq(module), eq(scope), eq(n), eq(parent), eq("globalVar"));
    }

    @Test
    public void testCollect_HandleSetFromLocal() {
        Node n = mockNode(Token.NAME, "x");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.VAR);
        when(n.getFirstChild()).thenReturn(null);

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("x"), eq(scope));
        doReturn(false).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromLocal(eq(module), eq(scope), eq(n), eq(parent), eq("x"));
    }

    @Test
    public void testCollect_DefaultCase_Return() {
        Node n = mockNode(Token.OTHER, null);
        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).isGlobalNameReference(any(), any());
    }
}
